// Package seccomp compiles per-architecture syscall policies into classic
// BPF (cBPF) programs suitable for a seccomp-style sandbox controller, and
// provides an independent interpreter used to verify compiled programs
// against the policy semantics.
//
// Programs operate on a seccomp_data-like context:
//
//	offset 0:  int32  syscall number
//	offset 4:  uint32 architecture (AUDIT_ARCH_*)
//	offset 16: uint64 args[6]
//
// 64-bit arguments are accessed as two 32-bit words, low word first
// (little-endian targets). All jumps generated by the compiler are forward.
package seccomp

// Classic BPF opcodes (Linux BPF_* encoding).
const (
	opLdWAbs = 0x20 // BPF_LD  | BPF_W | BPF_ABS
	opJa     = 0x05 // BPF_JMP | BPF_JA
	opJeqK   = 0x15 // BPF_JMP | BPF_JEQ | BPF_K
	opJgtK   = 0x25 // BPF_JMP | BPF_JGT | BPF_K
	opJgeK   = 0x35 // BPF_JMP | BPF_JGE | BPF_K
	opAndK   = 0x54 // BPF_ALU | BPF_AND | BPF_K
	opRetK   = 0x06 // BPF_RET | BPF_K
	opRetA   = 0x16 // BPF_RET | BPF_A
)

// Instruction is a single classic BPF instruction (struct sock_filter).
type Instruction struct {
	Code uint16
	JT   uint8
	JF   uint8
	K    uint32
}

// seccomp_data field offsets.
const (
	offNr   = 0
	offArch = 4
	offArgs = 16
	numArgs = 6
)

// argLoOff and argHiOff return the byte offsets of the low and high 32-bit
// words of argument i (little-endian layout).
func argLoOff(i int) uint32 { return offArgs + 8*uint32(i) }
func argHiOff(i int) uint32 { return offArgs + 8*uint32(i) + 4 }

// Return actions (SECCOMP_RET_*).
const (
	ActionAllow  uint32 = 0x7FFF0000     // SECCOMP_RET_ALLOW
	ActionReject uint32 = 0x00050000 | 1 // SECCOMP_RET_ERRNO | EPERM
)
